 61	type recorder struct {
 62		mu     sync.Mutex
 63		events []string
 64	}
 65	
 66	func (r *recorder) Publish(_ context.Context, ev Event) error {
 67		r.mu.Lock()
 68		defer r.mu.Unlock()
 69		r.events = append(r.events, ev.Type)
 70		return nil
 71	}
