func TestCanTransition(t *testing.T) {
	allowed := map[[2]Status]bool{
		{StatusCreated, StatusPending}:   true,
		{StatusCreated, StatusDeclined}:  true,
		{StatusPending, StatusSucceeded}: true,
		{StatusPending, StatusDeclined}:  true,
		{StatusSucceeded, StatusRefunded}: true,
	}
	candidates := append([]Status{"", "UNKNOWN"}, allStatuses...)
	for _, from := range candidates {
		for _, to := range candidates {
			want := allowed[[2]Status{from, to}]
			if got := CanTransition(from, to); got != want {
				t.Errorf("CanTransition(%q, %q) = %v, want %v", from, to, got, want)
			}
		}
	}
}

func TestStatusFinal(t *testing.T) {
	final := map[Status]bool{
		StatusDeclined: true,
		StatusRefunded: true,
	}
	for _, st := range append([]Status{"", "UNKNOWN"}, allStatuses...) {
		if got, want := st.Final(), final[st]; got != want {
			t.Errorf("Status(%q).Final() = %v, want %v", st, got, want)
		}
	}
}

