  1	package payment
  2	
  3	import (
  4		"context"
  5		"fmt"
  6		"sync"
  7	
  8		"example.com/gopayments/clock"
  9		"example.com/gopayments/money"
 10	)
 11	
 12	// IDGenerator creates unique identifiers with a type prefix.
 13	type IDGenerator interface {
 14		NewID(prefix string) string
 15	}
 16	
 17	// SeqIDs is a deterministic IDGenerator ("pay_000001", "ref_000002", ...).
 18	type SeqIDs struct {
 19		mu sync.Mutex
 20		n  int
 21	}
 22	
 23	// NewSeqIDs returns a sequential generator starting at 1.
 24	func NewSeqIDs() *SeqIDs { return &SeqIDs{} }
 25	
 26	// NewID returns the next identifier.
 27	func (g *SeqIDs) NewID(prefix string) string {
 28		g.mu.Lock()
 29		defer g.mu.Unlock()
 30		g.n++
 31		return fmt.Sprintf("%s_%06d", prefix, g.n)
 32	}
 33	
 34	// Config tunes the service.
 35	type Config struct {
 36		// FeeBps is the processing fee in basis points charged on every payment.
 37		FeeBps int64
 38	}
 39	
 40	// Service drives the payment lifecycle.
 41	type Service struct {
 42		repo   Repository
 43		clock  clock.Clock
 44		ids    IDGenerator
 45		events Publisher
 46		cfg    Config
 47	}
 48	
 49	// NewService wires a Service. events may be nil.
 50	func NewService(repo Repository, clk clock.Clock, ids IDGenerator, events Publisher, cfg Config) *Service {
 51		return &Service{repo: repo, clock: clk, ids: ids, events: events, cfg: cfg}
 52	}
 53	
 54	// CreateInput is the input of Create.
 55	type CreateInput struct {
 56		MerchantID string
 57		Amount     money.Amount
 58	}
 59	
 60	// Create registers a new payment in status CREATED.
 61	func (s *Service) Create(ctx context.Context, in CreateInput) (Payment, error) {
 62		if in.MerchantID == "" {
 63			return Payment{}, fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
 64		}
 65		if !in.Amount.IsPositive() {
 66			return Payment{}, fmt.Errorf("%w: amount must be positive, got %s", ErrInvalidInput, in.Amount)
 67		}
 68		fee, err := money.Fee(in.Amount, s.cfg.FeeBps)
 69		if err != nil {
 70			return Payment{}, fmt.Errorf("compute fee: %w", err)
 71		}
 72		now := s.clock.Now()
 73		p := Payment{
 74			ID:         s.ids.NewID("pay"),
 75			MerchantID: in.MerchantID,
 76			Amount:     in.Amount,
 77			Fee:        fee,
 78			Status:     StatusCreated,
 79			Version:    1,
 80			CreatedAt:  now,
 81			UpdatedAt:  now,
 82		}
 83		if err := s.repo.Create(ctx, p); err != nil {
 84			return Payment{}, fmt.Errorf("create payment: %w", err)
 85		}
 86		s.publish(ctx, Event{Type: "payment.created", Payment: p})
 87		return p, nil
 88	}
 89	
 90	// Get loads a payment.
 91	func (s *Service) Get(ctx context.Context, id string) (Payment, error) {
 92		p, err := s.repo.Get(ctx, id)
 93		if err != nil {
 94			return Payment{}, fmt.Errorf("get payment %s: %w", id, err)
 95		}
 96		return p, nil
 97	}
 98	
 99	// List returns one page of a merchant's payments.
100	func (s *Service) List(ctx context.Context, merchantID string, page Page) ([]Payment, string, error) {
101		if merchantID == "" {
102			return nil, "", fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
103		}
104		ps, next, err := s.repo.ListByMerchant(ctx, merchantID, page)
105		if err != nil {
106			return nil, "", fmt.Errorf("list payments of %s: %w", merchantID, err)
107		}
108		return ps, next, nil
109	}
110	
111	// Authorize moves a CREATED payment to PENDING (sent to the provider).
112	func (s *Service) Authorize(ctx context.Context, id string) (Payment, error) {
113		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
114			if !CanTransition(p.Status, StatusPending) {
115				return Event{}, fmt.Errorf("%w: cannot authorize a %s payment", ErrInvalidTransition, p.Status)
116			}
117			p.Status = StatusPending
118			return Event{Type: "payment.pending"}, nil
119		})
120	}
121	
122	// Capture moves a PENDING payment to SUCCEEDED.
123	func (s *Service) Capture(ctx context.Context, id string) (Payment, error) {
124		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
125			if !CanTransition(p.Status, StatusSucceeded) {
126				return Event{}, fmt.Errorf("%w: cannot capture a %s payment", ErrInvalidTransition, p.Status)
127			}
128			p.Status = StatusSucceeded
129			return Event{Type: "payment.succeeded"}, nil
130		})
131	}
132	
133	// Decline moves a CREATED or PENDING payment to DECLINED.
134	func (s *Service) Decline(ctx context.Context, id, reason string) (Payment, error) {
135		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
136			if !CanTransition(p.Status, StatusDeclined) {
137				return Event{}, fmt.Errorf("%w: cannot decline a %s payment", ErrInvalidTransition, p.Status)
138			}
139			p.Status = StatusDeclined
140			p.DeclineReason = reason
141			return Event{Type: "payment.declined"}, nil
142		})
143	}
144	
145	// Refund refunds amount of a SUCCEEDED payment. Partial refunds keep the
146	// payment SUCCEEDED; once the whole amount is refunded it becomes REFUNDED.
147	func (s *Service) Refund(ctx context.Context, id string, amount money.Amount) (Payment, Refund, error) {
148		if !amount.IsPositive() {
149			return Payment{}, Refund{}, fmt.Errorf("%w: refund amount must be positive, got %s", ErrInvalidInput, amount)
150		}
151		var refund Refund
152		p, err := s.mutate(ctx, id, func(p *Payment) (Event, error) {
153			if !CanTransition(p.Status, StatusRefunded) {
154				return Event{}, fmt.Errorf("%w: cannot refund a %s payment", ErrInvalidTransition, p.Status)
155			}
156			if amount.Currency != p.Amount.Currency {
157				return Event{}, fmt.Errorf("%w: refund in %s for a %s payment", money.ErrCurrencyMismatch, amount.Currency.Code, p.Amount.Currency.Code)
158			}
159			if amount.Minor > p.Remaining().Minor {
160				return Event{}, fmt.Errorf("%w: requested %s, remaining %s", ErrRefundExceedsRemaining, amount, p.Remaining())
161			}
162			refund = Refund{ID: s.ids.NewID("ref"), Amount: amount, CreatedAt: s.clock.Now()}
163			p.Refunded += amount.Minor
164			p.Refunds = append(p.Refunds, refund)
165			evType := "payment.partially_refunded"
166			if p.Refunded == p.Amount.Minor {
167				p.Status = StatusRefunded
168				evType = "payment.refunded"
169			}
170			return Event{Type: evType, Refund: &refund}, nil
171		})
172		if err != nil {
173			return Payment{}, Refund{}, err
174		}
175		return p, refund, nil
176	}
177	
178	// mutate loads a payment, applies change and saves it with optimistic locking.
179	func (s *Service) mutate(ctx context.Context, id string, change func(p *Payment) (Event, error)) (Payment, error) {
180		p, err := s.repo.Get(ctx, id)
181		if err != nil {
182			return Payment{}, fmt.Errorf("load payment %s: %w", id, err)
183		}
184		ev, err := change(&p)
185		if err != nil {
186			return Payment{}, fmt.Errorf("payment %s: %w", id, err)
187		}
188		p.UpdatedAt = s.clock.Now()
189		if err := s.repo.Update(ctx, p); err != nil {
190			return Payment{}, fmt.Errorf("save payment %s: %w", id, err)
191		}
192		p.Version++
193		ev.Payment = p
194		s.publish(ctx, ev)
195		return p, nil
196	}
197	
198	func (s *Service) publish(ctx context.Context, ev Event) {
199		if s.events == nil {
200			return
201		}
202		// Delivery is asynchronous and retried by the dispatcher; a failure to
203		// enqueue must not fail the payment operation.
204		_ = s.events.Publish(ctx, ev)
205	}
